import { externalGearPair, sliderCrank } from '/leitor/mechanics.mjs';
// Steam-driven three-roller cane mill: deterministic, qualitative teaching model.
// Gearing: involute, module 0.5 -> pinion 20 teeth (pitch radius 5), wheel 104 teeth (pitch radius 26).
const CZ = 20, TOPZ = 38, CDIST = 31; // centre distance = 5 + 26
const CX = 10, TOPX = CX + Math.sqrt(CDIST ** 2 - (TOPZ - CZ) ** 2);
export const DIM = {
  crank: { x: CX, z: CZ, r: 7 }, rod: 24, pistonRod: 26, cylY: -52,
  cyl: { x0: -54, x1: -28, r: 6 },
  boiler: { x: -78, y: -16, r: 13, h: 50 },
  module: 0.5, nPinion: 20, nGear: 104,
  pinion: 5, gear: 26, gearY: -24, flyY: -40, flyR: 16,
  top: { x: TOPX, z: TOPZ }, left: { x: TOPX - 10, z: 22 }, right: { x: TOPX + 10, z: 22 }, rollR: 8.97,
  rollY0: 8, rollY1: 36, pMin: 2, pMax: 9,
};
export const PAIR = externalGearPair({ teethA: DIM.nPinion, teethB: DIM.nGear, module: DIM.module, samples: 8 });
if (Math.abs(PAIR.distance - CDIST) > 1e-9) throw new Error('gear centre distance mismatch');
export const RATIO = DIM.nGear / DIM.nPinion; // 5.2

export function init() {
  return { t: 0, fire: 40, pressure: 1, valve: false, angle: 0, omega: 0,
    queue: 0, caneIn: 0, crushed: 0, juice: 0, msg: 'Boiler warming. Raise the fire and wait for pressure.' };
}

export function setFire(s, v) { return { ...s, fire: Math.max(0, Math.min(100, +v)) }; }

export function toggleValve(s) {
  if (!s.valve && s.pressure < DIM.pMin)
    return { ...s, msg: `Blocked: gauge reads ${s.pressure.toFixed(1)}, below the ${DIM.pMin} needed to move the piston.` };
  return { ...s, valve: !s.valve, msg: s.valve ? 'Throttle closed: engine coasting to a stop.' : 'Throttle open: steam drives the piston.' };
}

export function feed(s) {
  if (rollerRpm(s) < 1) return { ...s, msg: 'Blocked: the rollers are stopped; cane would jam the mill.' };
  return { ...s, queue: s.queue + 1, msg: 'Cane stalk fed between the rollers.' };
}

export function rollerRpm(s) { return (s.omega / RATIO) * 60 / (2 * Math.PI); }

export function step(s, dt) {
  let n = { ...s };
  const h = 0.05;
  for (let t = 0; t < dt - 1e-9; t += h) {
    const d = Math.min(h, dt - t);
    const loading = n.caneIn > 0 ? 1 : 0;
    const use = n.valve ? 0.045 * n.omega : 0;
    n.pressure = Math.max(1, Math.min(DIM.pMax, n.pressure + d * (n.fire * 0.012 - use - 0.03 * (n.pressure - 1))));
    const drive = n.valve && n.pressure > 1.2 ? 2.6 * (n.pressure - 1.2) : 0;
    const target = Math.max(0, drive - loading * 3);
    n.omega += (target - n.omega) * Math.min(1, d * 0.8);
    if (n.omega < 0.02 && !n.valve) n.omega = 0;
    n.angle = (n.angle + n.omega * d) % (Math.PI * 2 * DIM.nGear);
    if (n.caneIn <= 0 && n.queue > 0) { n.queue--; n.caneIn = 1; }
    if (n.caneIn > 0) {
      const surf = (n.omega / RATIO) * DIM.rollR; // cm/s surface speed
      const adv = surf * d / ROUTE.journey;
      const a = Math.min(adv, n.caneIn);
      n.caneIn -= a; n.crushed += a; n.juice += a; // qualitative: trough fill tracks crushed stalks
    }
    n.t += d;
  }
  return n;
}

// One shared vertical plane y = cylY: local slider-crank X -> world x, local Y -> world z.
export function pose(s) {
  const { x, z, r } = DIM.crank;
  const th = s.angle;
  const sc = sliderCrank({ radius: r, rodLength: DIM.rod, side: -1 }, th);
  const [pa, pb] = PAIR.phaseAt(th);
  return { th, pin: [x + sc.pin[0], DIM.cylY, z + sc.pin[1]], cross: [x + sc.slider[0], DIM.cylY, z + sc.slider[1]],
    stroke: sc.stroke, pinionA: pa, wheelA: pb, roll: pb - Math.PI - Math.PI / DIM.nGear, piston: x + sc.slider[0] - DIM.pistonRod };
}

export function readouts(s) {
  return {
    pressure: s.pressure.toFixed(1) + ' (teaching gauge)',
    engine: (s.omega * 60 / (2 * Math.PI)).toFixed(0) + ' rpm',
    rollers: rollerRpm(s).toFixed(1) + ' rpm',
    juice: s.juice <= 0 ? 'trough empty' : s.caneIn > 0 ? 'draining into trough' : 'collected in trough',
    crushed: s.crushed.toFixed(1) + ' stalks',
  };
}


// Tangent entry -> underside of top roll -> top of the delivery roll -> chute.
// Every join is position- and tangent-continuous in the actual roller XZ plane.
const RPATH=Math.hypot(5,8), A0=Math.atan2(-8,5), A1=Math.atan2(-8,-5);
const B0=Math.atan2(8,5), B1=155*Math.PI/180;
const entry=[35,48.75], nipIn=[5,30], nipOut=[-5,30];
const entryLength=Math.hypot(entry[0]-nipIn[0],entry[1]-nipIn[1]);
const bendLength=RPATH*(A0-A1),deliveryLength=RPATH*(B1-B0),exitLength=18;
const outStart=[-10+RPATH*Math.cos(B1),22+RPATH*Math.sin(B1)];
const exit=[outStart[0]-exitLength*Math.sin(B1),outStart[1]+exitLength*Math.cos(B1)];
const length=entryLength+bendLength+deliveryLength+exitLength,headStart=entryLength-1,stalkLength=56;
export const ROUTE={length,entryLength,bendLength,deliveryLength,exitLength,nipIn,nipOut,entry,exit,outStart,radius:RPATH,headStart,stalkLength,journey:length+stalkLength-headStart};
export function routePoint(distance){
 const d=Math.max(0,Math.min(ROUTE.length,distance));let x,z;
 if(d<=entryLength){const t=d/entryLength;x=entry[0]+t*(nipIn[0]-entry[0]);z=entry[1]+t*(nipIn[1]-entry[1]);}
 else if(d<=entryLength+bendLength){const a=A0-(d-entryLength)/RPATH;x=RPATH*Math.cos(a);z=DIM.top.z+RPATH*Math.sin(a);}
 else if(d<=entryLength+bendLength+deliveryLength){const a=B0+(d-entryLength-bendLength)/RPATH;x=-10+RPATH*Math.cos(a);z=22+RPATH*Math.sin(a);}
 else{const t=(d-entryLength-bendLength-deliveryLength)/exitLength;x=outStart[0]+t*(exit[0]-outStart[0]);z=outStart[1]+t*(exit[1]-outStart[1]);}
 return [DIM.top.x+x,22,z];
}
export function routeRadius(distance){
 if(distance>=entryLength)return .45;
 return Math.max(.45,Math.min(.65,Math.hypot(RPATH,entryLength-distance)-DIM.rollR-.025));
}
export function materialPose(s){
 const progress=s.caneIn>0?1-s.caneIn:0,head=ROUTE.headStart+progress*ROUTE.journey,tail=head-ROUTE.stalkLength,points=[];
 if(s.caneIn>0)for(let d=Math.max(0,tail);d<=Math.min(ROUTE.length,head);d+=.65)points.push({d,p:routePoint(d),pressed:d>=entryLength-6});
 return {progress,head,tail,points};
}

