import * as M from './model.mjs';
import { camera, draw } from './geometry.mjs';

export function mount(root, env) {
  let view='all'; let s = M.init(), reduced = env.reducedMotion, visible = true, raf = 0, last = 0, insp = false, paused=false;
  root.innerHTML = `<div class="mill">
  <header class="mill-heading"><span>STEAM-DRIVEN CANE MILL</span><span>20 : 104</span></header><svg id="art" class="iso" viewBox="0 0 900 520" role="img" aria-label="Steam engine driving a three-roller sugar-cane mill"></svg>
  <div class="controls">
    <label>Firebox heat <input id="fire" type="range" min="0" max="100" step="5"></label>
    <button id="valve" type="button">Open throttle</button>
    <button id="feed" type="button">Feed cane</button>
    <button id="advance" type="button">Run 10 s</button>
    <button id="step" type="button">Step 1 s</button><button id="engine-view" type="button" aria-pressed="false">Engine detail</button><button id="gear-view" type="button" aria-pressed="false">Gear detail</button><button id="mill-view" type="button" aria-pressed="false">Cane path</button><button id="whole-view" type="button" aria-pressed="true">Whole mill</button><button id="insp" type="button" aria-pressed="false">Inspect housings</button>
    <button id="pause" type="button">Pause motion</button><button id="reset" type="button">Reset</button>
  </div>
  <label id="phase-control" class="phase-control" for="phase">Explore crank position<input id="phase" type="range" min="0" max="360" value="0" step="5"></label><p id="view-label" class="view-label"></p><p id="legend" class="legend"></p><details id="cutaway-note" class="cutaway-note"><summary>About this cutaway</summary><p id="cutaway-note-text"></p></details><ul id="key" class="key"></ul><dl class="read">
    <div><dt>Boiler</dt><dd id="r-p"></dd></div><div><dt>Engine</dt><dd id="r-e"></dd></div>
    <div><dt>Rollers</dt><dd id="r-r"></dd></div><div><dt>Crushed</dt><dd id="r-c"></dd></div>
    <div><dt>Juice</dt><dd id="r-j"></dd></div>
  </dl>
  <p id="status" role="status" aria-live="polite"></p></div>`;
  const $ = (id) => root.querySelector('#' + id);
  const svg = $('art');
  function render() {
    const shown=insp&&view==='all'?'mill':view;
    const narrow=(root.getBoundingClientRect().width||900)<600,W=narrow?460:900,H=narrow?(shown==='gears'?640:shown==='mill'?600:400):520;
    svg.setAttribute('viewBox',`${0} ${0} ${W} ${H}`);
    const notes={
      gears:'A steel 20-tooth pinion on the crankshaft drives the brass 104-tooth wheel on the top-roller shaft. Their pitch circles touch at a centre distance of 31. The wheel turns 20/104 as fast, in the opposite direction. This isolated drive view deliberately omits the cylinder, crank plate, flywheel and mill barrels; the shaft stubs and seated bearings remain.',
      engine:'The front half of the cylinder shell is removed. Inside its bore, a solid brass piston with two dark rings slides on a steel rod. The rod passes through the annular gland to the guided forked crosshead. The nearest upper guide cap is removed only in this detail to expose the joint. The slim forged rod ends in an eye between the two brass clevis cheeks, joined by their shared pin. The connecting rod joins its pin to the eccentric pin of the round crank plate. The steam chest and two ports sit behind the open bore. The boiler pipe is omitted here; its inlet flange is seated directly on the supported steam chest. The front crankshaft bearing and output pinion remain visible; the flywheel and driven wheel are omitted in this close-up.',
      mill:'Follow the green stalk from the sloping feed bed into the first nip, across the curved turner plate under the top roller, and through the second nip. In the end section, 1 and 2 mark these two gaps; arrows show the material direction. The delivery roll carries the flattened beige fibre over its short crown to the steep downward discharge chute. The solid band is a finite moving stalk: its gold dot marks the leading tip. The faint dashed guide traces the rest of its route; step forward to watch the tip reach the outlet. Golden juice drips from the exposed underside of each lower barrel into the open liquid tray. A separate shallow receiver under the chute holds discharged bagasse; its fibrous contents stay outside the juice vessel. The inset includes the full entry and downward exit: it is a true end section of the same working gaps, shown with enlarged fibre clearances. Barrels are shortened to expose their rear journals and bearing seats. Rear journals sit in bored, bolted flange housings on an open gantry and pedestals connected to the foundation. Inspection removes the front journal frame, forward shaft lengths, front barrel lengths and front feed-bed legs to expose the actual working plane. The complete machine retains these parts; engine and external gearing are omitted from this detail.',
      all:'Boiler → sectioned cylinder → crosshead and crank → 20:104 reduction → three crushing rollers. Follow the sloping feed bed and separate discharge chute; use Cane path for the two nips and juice collection.'};
    const legends={
      all:notes.all,
      engine:'Steam moves the ringed piston inside the open bore. Its rod passes through the gland into the guided crosshead. The connecting rod turns the eccentric crank pin. Pause and scrub to inspect the full stroke.',
      gears:'The steel pinion has 20 teeth; the brass wheel has 104. The wheel turns 20/104 as fast, in the opposite direction. Continuous shafts run through their hubs into seated bearings. The inset shows their actual tooth mesh.',
      mill:'Green cane passes two crushing gaps, marked 1 and 2. A curved plate guides transfer; beige fibre crosses the delivery crown before the downhill chute and bagasse bin. Golden juice falls into its own tray. The gold dot marks the moving tip: step forward to follow it.'
    };
    $('legend').textContent=legends[shown];
    $('cutaway-note-text').textContent=notes[shown];
    $('cutaway-note').hidden=shown==='all';
    const sw=(c,t)=>`<li><i style="background:${c}"></i>${t}</li>`;
    $('key').innerHTML=shown==='gears'?sw('#838d89','Steel · pinion, 20 teeth')+sw('#b39a5c','Brass · driven wheel, 104 teeth')
      :shown==='engine'?sw('#b39a5c','Solid piston')+sw('#46423a','Piston rings')+sw('#a4aaa6','Rod and crosshead')
      :sw('#789145','Cane · feed')+sw('#bfab7d','Bagasse · discharge')+sw('#c99a2e','Juice · tray');
    svg.innerHTML = draw(s,camera(W,H,shown),shown,false);
    for(const [id,key] of [['engine-view','engine'],['gear-view','gears'],['whole-view','all'],['mill-view','mill']])$(id).setAttribute('aria-pressed',String(shown===key));
    svg.classList.toggle('inspect', insp);
    const r = M.readouts(s);
    $('r-p').textContent = r.pressure; $('r-e').textContent = r.engine; $('r-r').textContent = r.rollers;
    $('r-c').textContent=r.crushed; $('r-j').textContent=r.juice;
    $('view-label').textContent=(insp?'Inspection · ':'')+({all:'Whole mill',engine:'Engine detail · cylinder section',gears:'Gear detail · isolated drive',mill:'Cane path · barrel and journal cutaway'}[shown]);
    $('phase-control').hidden=shown!=='engine'&&shown!=='gears';
    $('phase').value=String((s.angle*180/Math.PI)%360);
    $('pause').textContent=paused?'Resume motion':'Pause motion';
    $('fire').value = s.fire; $('valve').textContent = s.valve ? 'Close throttle' : 'Open throttle';
    $('insp').setAttribute('aria-pressed', String(insp));
    $('status').textContent=s.msg;
  }
  const on = (id, ev, f) => $(id).addEventListener(ev, f);
  on('fire', 'input', (e) => { s = M.setFire(s, e.target.value); render(); });
  on('valve', 'click', () => { s = M.toggleValve(s); render(); });
  on('feed', 'click', () => { s = M.feed(s); render(); });
  on('insp', 'click', () => { insp = !insp; render(); });
  on('advance','click',()=>{s=M.step(s,10);render();});
  on('step','click',()=>{s=M.step(s,1);render();});
  on('engine-view','click',()=>{view='engine';render();});
  on('gear-view','click',()=>{view='gears';render();});
  on('mill-view','click',()=>{view='mill';render();});
  on('pause','click',()=>{paused=!paused;if(paused){cancelAnimationFrame(raf);raf=0;}else start();render();});
  on('phase','input',e=>{paused=true;cancelAnimationFrame(raf);raf=0;s={...s,angle:Number(e.target.value)*Math.PI/180};render();});
  on('whole-view','click',()=>{view='all';insp=false;render();});
  on('reset','click',()=>{s=M.init();view='all';insp=false;paused=false;render();start();});
  function loop(t) {
    raf = 0;
    if (!visible || reduced) return;
    const dt = Math.min(0.1, (t - (last || t)) / 1000); last = t;
    if(!paused)s = M.step(s, dt); render(); raf = requestAnimationFrame(loop);
  }
  const start = () => { if (!raf && visible && !reduced && !paused) { last = 0; raf = requestAnimationFrame(loop); } };
  const envH = (e) => { const d = e.detail || {}; if ('visible' in d) visible = d.visible; if ('reducedMotion' in d) reduced = d.reducedMotion; if (raf && (!visible || reduced)) { cancelAnimationFrame(raf); raf = 0; } start(); };
  root.addEventListener('figure:environment', envH);
  let layoutWidth=Math.round(root.getBoundingClientRect().width);
  const resize=new ResizeObserver(()=>{const width=Math.round(root.getBoundingClientRect().width);if(width!==layoutWidth){layoutWidth=width;render();}});
  resize.observe(root);
  render(); start();
  return () => { resize.disconnect(); if (raf) cancelAnimationFrame(raf); root.removeEventListener('figure:environment', envH); root.innerHTML = ''; };
}

