import * as k from '/kit/iso-kit.mjs';
import * as G from '/kit/lathe.mjs';
import {mPrism,mItems,mSvg,mArc,mFace} from '/kit/facets.mjs';
import {DIM,PAIR,pose,ROUTE,routePoint,routeRadius,materialPose} from './model.mjs';
const X=[1,0,0],Y=[0,1,0];
